        this.getReferenceValueForField = function (field, valueType) {
            return new Promise((resolve, reject) => {
                const innerObject = {};
                innerObject[field] = valueType === 'newest' ? {order: 'desc'} : {order: 'asc'};
                const elasticsearchParameters = {
                    _source: [field],
                    size: 1,
                    sort: innerObject,
                };

                BaseUtils.logMessage( BaseUtils.LogLevelType["DEBUG"], 'Will send elasticsearch request using parameters', JSON.stringify(elasticsearchParameters));

                _adjustParametersThenSendViaAjax( m_elasticsearchModelOptions.elasticsearchIndex, '_search', elasticsearchParameters )
                    .then( data => {
                        const hits = data.hits.hits[0];

                        if (hits && hits._source) {
                            const result = hits._source[field];
                            resolve(result);
                        } else {
                            BaseUtils.logMessage( BaseUtils.LogLevelType["WARN"], 'Could not find reference value of field ' + field);
                            reject({"message": I18nTranslator.i18n( 'exceptions.couldNotFindReferenceValueOfFieldXXX', field ) });
                        }
                    })
                    .catch( reject );
            });
        };
