         *
         * Watch out: field aggregationOptions.aggregationField should not reflect the name of the field to collect the values for
         *            but the name of the field in a single returned bucket, which is in general 'key' and sometimes
         *            'key_as_string' (when processing time values)
         */
        this.getPossibleValuesForDataDimensionFromAggregation = function (aggregationOptions, currentUserSettings) {
            return new Promise((resolve, reject) => {
                const resultHash = {};
                const bucketFieldContainingResult = aggregationOptions.aggregationField;

                const filterFunction = aggregationOptions.filterFunction
                    ? aggregationOptions.filterFunction
                    : function (x) {
                        return true;
                    };

                me.getPossibleObjectsForDataDimensionFromAggregation(aggregationOptions, currentUserSettings).then(aggregationHits => {
                    // This block will return just an array containing the values of attribute aggregationOptions.aggregationField of the objects in the aggregation
                    for (let i = 0; i < aggregationHits.length; i++) {
                        const currentHitObject = aggregationHits[i];
                        const isToStore = filterFunction(currentHitObject['key']);
                        if (isToStore) {
                            // bucketFieldContainingResult will in general be 'key' or 'key_as_string'
                            resultHash[currentHitObject[bucketFieldContainingResult]] = 1;
